        balance = 0
        for char in prefix:
            if char == '(':
                balance += 1
            else:
                balance -= 1
            if balance < 0:
                return False
        return True

    def backtrack(index):
        if index == n:
            if is_valid_prefix(s[:n]):
                return s
            return None

        if s[index] != '?':
            result = backtrack(index + 1)
            if result:
                return result

        s[index] = '('
        result = backtrack(index + 1)
        if result:
            return result

        s[index] = ')'
        result = backtrack(index + 1)
        if result:
            return result

        return None

    s = list(s)
    result = backtrack(0)
    if result:
        return ''.join(result)
    else:
        return ':('

